<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Holder\RoleUidAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the RoleUidAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class RoleUidAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getUid returns null on a freshly created holder.
     */
    public function testUidNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithRoleUidAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUidAssigned());
        $this->assertNull($holder->getUid());
    }
}
class ImplWithRoleUidAttributeHolderUnitTest
{
    use RoleUidAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUidRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUid();
    }
}
